INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'artificial', 'adj.', '/ˌɑːtɪˈfɪʃ(ə)l/', '人造的;人工的', 'Artificial machines can now learn from huge amounts of data.', '人造的机器现在能从海量数据中学习。', 'Artificial Intelligence', 1, 0, 'senior', 'wordlist', 'elective3', 'U4', 'artificial intelligence', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'artificial intelligence', 'n.', '/ˌɑːtɪˈfɪʃ(ə)l ɪnˈtelɪdʒəns/', '人工智能', 'Artificial intelligence may be our greatest achievement so far.', '人工智能也许是我们迄今为止最大的成就。', 'Artificial Intelligence', 2, 0, 'senior', 'wordlist', 'elective3', 'U4', 'develop artificial intelligence', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'intelligence', 'n.', '/ɪnˈtelɪdʒəns/', '智能;智力', 'Some people fear that machine intelligence may one day match human intelligence.', '有人担心机器智能有一天会赶上人类智能。', 'Artificial Intelligence', 3, 0, 'senior', 'wordlist', 'elective3', 'U4', 'human intelligence', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'humanity', 'n.', '/hjuːˈmænɪti/', '人类;人性', 'Hawking warned that AI could be the worst thing ever for humanity.', '霍金警告说,人工智能可能是人类有史以来最糟糕的东西。', 'Artificial Intelligence', 4, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a threat to humanity', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'assistant', 'n.', '/əˈsɪstənt/', '助手;助理', 'My phone has a smart assistant that answers any question at once.', '我的手机里有一个聪明的助手,能立刻回答任何问题。', 'Artificial Intelligence', 5, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a personal assistant', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'susceptible', 'adj.', '/səˈseptəb(ə)l/', '易受影响的;易受……伤害的', 'Unlike humans, self-driving cars are not susceptible to tiredness.', '与人类不同,自动驾驶汽车不会受疲劳影响。', 'Artificial Intelligence', 6, 0, 'senior', 'wordlist', 'elective3', 'U4', 'susceptible to error', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'victim', 'n.', '/ˈvɪktɪm/', '受害者', 'Taxi drivers could be among the first victims of automation.', '出租车司机可能是自动化最早的受害者之一。', 'Artificial Intelligence', 7, 0, 'senior', 'wordlist', 'elective3', 'U4', 'the first victims', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'potentially', 'adv.', '/pəˈtenʃ(ə)li/', '潜在地;可能地', 'Nearly every job is potentially at risk in the long run.', '从长远看,几乎每一份工作都可能面临风险。', 'Artificial Intelligence', 8, 0, 'senior', 'wordlist', 'elective3', 'U4', 'potentially at risk', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'automation', 'n.', '/ɔːtəˈmeɪʃ(ə)n/', '自动化', 'Half of these jobs may disappear because of automation.', '这些工作中有一半可能因自动化而消失。', 'Artificial Intelligence', 9, 0, 'senior', 'wordlist', 'elective3', 'U4', 'the rise of automation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'capacity', 'n.', '/kəˈpæsɪti/', '能力;容量', 'Much of the value of AI lies in its capacity to analyse data.', '人工智能的价值大多在于它分析数据的能力。', 'Artificial Intelligence', 10, 0, 'senior', 'wordlist', 'elective3', 'U4', 'the capacity to analyse', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'analyse', 'v.', '/ˈæn(ə)laɪz/', '分析', 'AI can analyse vast amounts of data in just a few seconds.', '人工智能能在短短几秒内分析海量数据。', 'Artificial Intelligence', 11, 0, 'senior', 'wordlist', 'elective3', 'U4', 'analyse data', '美式拼 analyze;美音 /ˈænəlaɪz/', 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'leap', 'n.', '/liːp/', '剧变;飞跃;跳跃', 'Super-intelligent AI could be the biggest leap forward in history.', '超级智能的人工智能可能是历史上最大的飞跃。', 'Artificial Intelligence', 12, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a leap forward', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'regulate', 'v.', '/ˈreɡjʊleɪt/', '控制;管理;规范', 'We have no choice but to embrace AI and regulate it.', '我们别无选择,只能接纳人工智能并对它加以管理。', 'Artificial Intelligence', 13, 0, 'senior', 'wordlist', 'elective3', 'U4', 'regulate AI', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'illegal', 'adj.', '/ɪˈliːɡ(ə)l/', '非法的;违法的', 'Saying "My AI did it" is no excuse for illegal behaviour.', '说一句"是我的AI干的"不能成为违法行为的借口。', 'Artificial Intelligence', 14, 0, 'senior', 'wordlist', 'elective3', 'U4', 'illegal behaviour', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'immoral', 'adj.', '/ɪˈmɒrəl/', '不道德的', 'Blaming a machine cannot make immoral actions acceptable.', '把责任推给机器并不能让不道德的行为变得可以接受。', 'Artificial Intelligence', 15, 0, 'senior', 'wordlist', 'elective3', 'U4', 'immoral behaviour', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'client', 'n.', '/ˈklaɪənt/', '客户;委托人', 'A large number of clients have been attracted to genetic testing.', '大量客户被基因检测所吸引。', 'Artificial Intelligence', 16, 0, 'senior', 'wordlist', 'elective3', 'U4', 'attract clients', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'cite', 'v.', '/saɪt/', '引用;引述;举出', 'The website cited one company that compared the talents of twins.', '该网站举出一家比较双胞胎天赋的公司为例。', 'Artificial Intelligence', 17, 0, 'senior', 'wordlist', 'elective3', 'U4', 'cite an example', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'assess', 'v.', '/əˈses/', '评价;评定', 'Bobby was assessed, and his talents were found to be mostly scientific.', '鲍比接受了评测,他的天赋被发现主要在科学方面。', 'Artificial Intelligence', 18, 0, 'senior', 'wordlist', 'elective3', 'U4', 'assess one''s talents', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'reckon', 'v.', '/ˈrekən/', '认为;以为;估计', 'I reckon that robot doctors are just around the corner.', '我认为机器人医生很快就会出现。', 'Artificial Intelligence', 19, 0, 'senior', 'wordlist', 'elective3', 'U4', 'I reckon that…', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'cell', 'n.', '/sel/', '细胞;小室', 'Tiny robots may one day remove cancerous cells from the body.', '微型机器人有朝一日也许能清除体内的癌细胞。', 'Artificial Intelligence', 20, 0, 'senior', 'wordlist', 'elective3', 'U4', 'cancerous cells', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'demand', 'n.', '/dɪˈmɑːnd/', '需要;需求', 'Companies plan to meet the growing demand for faster transport.', '各公司计划满足人们对更快捷交通日益增长的需求。', 'Artificial Intelligence', 21, 0, 'senior', 'wordlist', 'elective3', 'U4', 'on-demand services', '美音 /dɪˈmænd/', 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'cycle', 'n.', '/ˈsaɪk(ə)l/', '自行车;循环', 'Many cities already have elevated cycle paths above the streets.', '许多城市的街道上方已经建有高架自行车道。', 'Artificial Intelligence', 22, 0, 'senior', 'wordlist', 'elective3', 'U4', 'elevated cycle paths', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'mechanical', 'adj.', '/mɪˈkænɪk(ə)l/', '机械的', 'His father said Robutt was only a mechanical imitation of a dog.', '他父亲说罗巴特只是一只狗的机械仿制品。', 'Artificial Intelligence', 23, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a mechanical imitation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'imitation', 'n.', '/ˌɪmɪˈteɪʃ(ə)n/', '仿制品;模仿', 'Jimmy refused to believe his robot dog was just an imitation.', '吉米不肯相信他的机器狗只是个仿制品。', 'Artificial Intelligence', 24, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a clever imitation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'frown', 'v.', '/fraʊn/', '皱眉', 'Jimmy began to frown when his father called Robutt a machine.', '当父亲把罗巴特称作机器时,吉米皱起了眉头。', 'Artificial Intelligence', 25, 0, 'senior', 'wordlist', 'elective3', 'U4', 'frown at', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'tightly', 'adv.', '/ˈtaɪtli/', '紧紧地', 'Jimmy held the little robot dog tightly in his arms.', '吉米把那只小机器狗紧紧抱在怀里。', 'Artificial Intelligence', 26, 0, 'senior', 'wordlist', 'elective3', 'U4', 'hold tightly', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'desperate', 'adj.', '/ˈdesp(ə)rət/', '拼命的;绝望的', 'The desperate look on his face meant he would not change his mind.', '他脸上拼命的神情表明他不会改变主意。', 'Artificial Intelligence', 27, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a desperate look', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'clue', 'n.', '/kluː/', '线索;提示', 'Foreshadowing gives the reader a clue about what will happen next.', '伏笔给读者提供了接下来会发生什么的线索。', 'Artificial Intelligence', 28, 0, 'senior', 'wordlist', 'elective3', 'U4', 'give a clue', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'faulty', 'adj.', '/ˈfɔːlti/', '有故障的;有缺陷的', 'The news report blamed faulty robotics for the prison breakout.', '这则新闻把越狱事件归咎于有故障的机器人系统。', 'Artificial Intelligence', 29, 0, 'senior', 'wordlist', 'elective3', 'U4', 'faulty robotics', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'consistent', 'adj.', '/kənˈsɪstənt/', '一贯的;一致的', 'Check whether the language style of your story stays consistent.', '检查一下你的故事语言风格是否保持一致。', 'Artificial Intelligence', 30, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a consistent style', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'agile', 'adj.', '/ˈædʒaɪl/', '敏捷的;灵活的', 'On the Moon, Jimmy''s arms and legs were long and agile.', '在月球上,吉米的胳膊和腿又长又灵活。', 'Artificial Intelligence', 31, 0, 'senior', 'wordlist', 'elective3', 'U4', 'long and agile', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'slope', 'v.', '/sləʊp/', '倾斜;成斜坡', 'The outer side of the crater began to slope southward.', '环形山的外侧开始向南倾斜。', 'Artificial Intelligence', 32, 0, 'senior', 'wordlist', 'elective3', 'U4', 'slope southward', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'hop', 'n.', '/hɒp/', '跳跃;蹦', 'Jimmy raced up the slope in a light, floating hop.', '吉米以轻盈飘浮的跳跃冲上斜坡。', 'Artificial Intelligence', 33, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a floating hop', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'squeak', 'v.', '/skwiːk/', '发出吱吱声', 'The robot dog would squeak whenever Jimmy came near.', '每当吉米靠近,那只机器狗就会发出吱吱声。', 'Artificial Intelligence', 34, 0, 'senior', 'wordlist', 'elective3', 'U4', 'squeak happily', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'tendon', 'n.', '/ˈtendən/', '腱', 'Robutt had four legs and tendons of steel.', '罗巴特有四条腿和钢铁般的肌腱。', 'Artificial Intelligence', 35, 0, 'senior', 'wordlist', 'elective3', 'U4', 'tendons of steel', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'wavelength', 'n.', '/ˈweɪvleŋθ/', '波长;频道', 'Jimmy heard his father''s voice on his private wavelength.', '吉米在自己的私人频道上听到了父亲的声音。', 'Artificial Intelligence', 36, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a private wavelength', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'crater', 'n.', '/ˈkreɪtə/', '环形山;坑', 'Jimmy was playing out on the crater with his robot dog.', '吉米正和他的机器狗在环形山上玩耍。', 'Artificial Intelligence', 37, 0, 'senior', 'wordlist', 'elective3', 'U4', 'out on the crater', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bound', 'adj.', '/baʊnd/', '很可能的;一定会的', 'Old robots were bound to break down sooner or later.', '旧机器人迟早一定会出故障。', 'Artificial Intelligence', 38, 0, 'senior', 'wordlist', 'elective3', 'U4', 'be bound to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'horizon', 'n.', '/həˈraɪz(ə)n/', '地平线;眼界', 'AI doctors are on the horizon, even if they are not here yet.', '人工智能医生即将到来,尽管它们还未出现。', 'Artificial Intelligence', 39, 0, 'senior', 'wordlist', 'elective3', 'U4', 'on the horizon', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'mutt', 'n.', '/mʌt/', '杂种狗', 'He called the robot dog a robot-mutt, and that was how it got its name.', '他把这只机器狗叫作"机器杂种狗",名字就是这么来的。', 'Artificial Intelligence', 40, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a robot-mutt', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'positronic', 'adj.', '/ˌpɒzɪˈtrɒnɪk/', '正电子的', 'Robutt had a simple positronic brain inside its metal body.', '罗巴特的金属身体里有一个简单的正电子大脑。', 'Artificial Intelligence', 41, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a positronic brain', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'recommendation', 'n.', '/ˌrekəmenˈdeɪʃ(ə)n/', '推荐;建议', 'Every recommendation the assistant makes seems to suit me.', '这个助手给出的每一条推荐似乎都很适合我。', 'Artificial Intelligence', 42, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a great recommendation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'judgement', 'n.', '/ˈdʒʌdʒmənt/', '判断;判断力', 'Self-driving cars can make judgements based on the information they collect.', '自动驾驶汽车能根据收集到的信息作出判断。', 'Artificial Intelligence', 43, 0, 'senior', 'wordlist', 'elective3', 'U4', 'exercise judgement', '美式常拼 judgment;美音 /ˈdʒʌdʒmənt/', 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'independent', 'adj.', '/ˌɪndɪˈpendənt/', '独立的;自主的', 'A truly independent AI could think without any programming.', '真正独立的人工智能不需要任何编程就能思考。', 'Artificial Intelligence', 44, 0, 'senior', 'wordlist', 'elective3', 'U4', 'an independent form of AI', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'embrace', 'v.', '/ɪmˈbreɪs/', '欣然接受;拥抱', 'We may have to embrace AI rather than fear it.', '我们也许必须欣然接受人工智能,而不是惧怕它。', 'Artificial Intelligence', 45, 0, 'senior', 'wordlist', 'elective3', 'U4', 'embrace technology', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bank on', 'v.', '/ˌbæŋk ˈɒn/', '依靠;指望', 'I would not bank on patients trusting a robot doctor soon.', '我不会指望病人很快就会信任机器人医生。', 'Artificial Intelligence', 46, 0, 'senior', 'wordlist', 'elective3', 'U4', 'bank on sth', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe3u4.01', '①分数/百分比/most/half/part/the rest of + of 短语', 'A2', 12, '外研社版选择性必修第三册 U4 — 分数、百分比、most/half/part/the rest of 等 + of + 名词作主语时,谓语与 of 后面的名词保持一致:of 后是不可数名词或单数→用单数;of 后是复数名词→用复数。', 1, 'elective3', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe3u4.02', '②不定代词 + many a / more than one / the number of', 'A2', 12, '外研社版选择性必修第三册 U4 — each/every/either/neither/one(of)/everyone/everything/someone/nobody/none(正式)作主语→单数;both/all(+复数)→复数,all/none(+不可数)→单数;many a + 单数名词、more than one + 单数名词、the number of→单数;a number of→复数。', 2, 'elective3', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe3u4.03', '③就近原则(either…or / neither…nor / not only…but also)与 there be', 'A2', 12, '外研社版选择性必修第三册 U4 — either…or、neither…nor、not only…but also 连接并列主语时,谓语与最近的那个主语保持一致;there be 句型的谓语与紧跟其后的第一个名词保持一致。', 3, 'elective3', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U4' AND code='fe3u4.01'), 'Almost 50 per cent of US jobs ____ at risk from automation in the next 20 years.', 'are', 'is', 'be', 'being', 'A', '百分比 of 后是复数名词 jobs,谓语用复数 are。', 2, 1, 'mcq');
