INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U4' AND code='fe3u4.03'), 'Either you or your friend ____ to decide whether to trust the AI.', 'have', 'to have', 'has', 'having', 'C', 'either…or 连接主语,谓语与最近的 your friend 一致,用单数 has。', 2, 11, 'mcq');
