INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U4' AND code='fe3u4.03'), 'There ____ an assistant and several apps built into my new phone.', 'is', 'are', 'be', 'been', 'A', 'there be 与紧跟其后的第一个名词 an assistant 一致,用单数 is。', 2, 13, 'mcq');
