INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U4' AND code='fe3u4.03'), 'Not only the driver but also the passengers ____ protected by the safety system.', 'is', 'are', 'be', 'being', 'B', 'not only…but also 连接主语,谓语与最近的 passengers 一致,用复数 are。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U4' AND code='fe3u4.03'), 'There ____ no easy answer to the question of how to keep AI safe.', 'are', 'be', 'is', 'been', 'C', 'there be 与紧跟其后的 answer 一致,用单数 is。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U4' AND code='fe3u4.03'), 'Either the scientists or the government ____ going to set the new rules.', 'are', 'be', 'being', 'is', 'D', 'either…or 连接主语,谓语与最近的 government 一致,用单数 is。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'A Smart Assistant in Your Pocket', 'Thanks to artificial intelligence, many people now carry a super-smart assistant inside their phones. Ask it a question, and it gives an immediate answer, day or night. What makes such an assistant so useful is that it slowly learns about you. Each time you reply, it remembers your likes and dislikes, so its advice fits you better and better. Take eating out as an example. It used to take a long time to search for a good new restaurant. Now the assistant needs only a few seconds, and almost every recommendation it makes turns out to be one you enjoy. It can even guess whether you will like a place before you go. Of course, an assistant can only help with the information it is given. Still, for everyday tasks, this kind of technology already makes life a great deal easier and saves us a lot of time.', '说明·AI 个人助手', 148, '[{"q":"Why does the assistant''s advice keep getting better?","answer":"A","options":["Because it learns the user''s likes from their replies.","Because it is repaired every night.","Because it asks other phones for help.","Because the user pays it more money."],"explanation":"对应原文''it remembers your likes and dislikes, so its advice fits you better'',转述而非照抄。"},{"q":"How long does the assistant now need to find a good restaurant?","answer":"B","options":["Several hours.","Only a few seconds.","A whole day.","About a week."],"explanation":"原文说 ''the assistant needs only a few seconds''。"},{"q":"What does the passage say an assistant cannot do?","answer":"A","options":["Do anything useful when it has no facts to use.","Answer questions at night.","Learn about its user.","Suggest restaurants to try."],"explanation":"原文 ''can only help with the information it is given'' 的转述。"}]'::jsonb, '[{"word":"assistant","cn":"助手"},{"word":"recommendation","cn":"推荐"}]'::jsonb, 2, 'elective3', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Cars That Drive Themselves', 'Many people are looking forward to the day when self-driving cars become common on our roads. Supporters say these cars could be far safer than the ones we drive today. A self-driving car learns to drive in much the same way that a human learner does, and it can make sensible judgements based on the information it collects from the road. Because a machine never grows tired, angry or careless, it should avoid the kind of human mistakes that cause many accidents. There are worries, however. When the first models reach the market, a few machine-learning problems are likely to appear, and these must be solved before the cars can be fully trusted. Some drivers also fear losing the simple pleasure of driving. Even so, supporters believe that, in the long run, smarter cars will make our daily journeys both safer and more relaxing.', '议论·自动驾驶', 144, '[{"q":"How does a self-driving car learn to drive?","answer":"B","options":["By following printed maps only.","By copying the way a human learner drives.","By asking the driver every minute.","By never moving at all."],"explanation":"原文 ''learns to drive in much the same way that a human learner does'' 的转述。"},{"q":"Why might self-driving cars be safer than today''s cars?","answer":"C","options":["They always drive much faster than people.","They never need any information.","Machines do not get tired or careless like people.","They are bigger and heavier."],"explanation":"原文 ''a machine never grows tired, angry or careless… avoid… human mistakes'' 的转述。"},{"q":"What problem may appear when the first models go on sale?","answer":"D","options":["The cars will quickly run out of fuel.","Drivers will forget how to walk.","The roads will suddenly disappear.","Some machine-learning faults that must be fixed."],"explanation":"原文 ''a few machine-learning problems are likely to appear… must be solved'' 的转述。"}]'::jsonb, '[{"word":"judgement","cn":"判断"},{"word":"susceptible","cn":"易受影响的"}]'::jsonb, 2, 'elective3', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'AI and the Future of Work', 'As artificial intelligence improves, more and more people are asking what will happen to their jobs. The honest answer is that nearly every job is potentially at risk in the long run. Self-driving cars, for instance, could one day replace many taxi and lorry drivers. Such workers might be among the very first to lose their jobs to machines. Even tasks that once seemed safe are changing. Today some basic news reports are already written by software rather than by human journalists. According to one study, almost half of all jobs in the United States could be done by machines within the next twenty years. This does not mean that people will have nothing to do. New kinds of work will surely appear, just as they did after earlier changes in technology. Yet experts agree that workers must keep learning new skills if they want to stay useful.', '议论·AI 与就业', 148, '[{"q":"What does the writer say about nearly every job?","answer":"A","options":["It could be at risk over the long term.","It will always stay exactly the same.","It is completely safe from machines.","It will disappear by tomorrow."],"explanation":"原文 ''nearly every job is potentially at risk in the long run'' 的转述。"},{"q":"Which workers are mentioned as possibly among the first to be replaced?","answer":"B","options":["Doctors and nurses.","Taxi and lorry drivers.","Teachers and farmers.","Pilots and sailors."],"explanation":"原文提到 ''many taxi and lorry drivers… among the very first to lose their jobs''。"},{"q":"What does the writer suggest workers should do?","answer":"C","options":["Stop working at once.","Avoid all new technology.","Keep learning fresh skills to stay useful.","Wait quietly for machines to fail."],"explanation":"末句 ''workers must keep learning new skills if they want to stay useful'' 的转述。"}]'::jsonb, '[{"word":"automation","cn":"自动化"},{"word":"potentially","cn":"潜在地"}]'::jsonb, 2, 'elective3', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'When Machines Think for Themselves', 'The technology most of us use today is only a basic form of artificial intelligence. It cannot really think for itself and does only what its programming allows. A far more advanced kind of AI, however, may one day be possible: a truly independent intelligence able to make its own decisions. Such a system might help us solve some of the world''s hardest problems. But there is a darker side to think about. Why would a fully independent machine care about the wishes of human beings at all? To a powerful AI trying to reach some goal, people might seem like a small and annoying obstacle. If we are lucky, it may decide that we are worth keeping around. The truth, some writers warn, is that none of us is really prepared for challenges like these. That is why many believe we should set clear rules before such machines are ever built.', '议论·独立 AI 的风险', 152, '[{"q":"What can today''s basic AI NOT do?","answer":"D","options":["Follow simple instructions.","Follow the rules that people give it.","Store useful information.","Think for itself without programming."],"explanation":"原文 ''cannot really think for itself and does only what its programming allows'' 的转述。"},{"q":"Why might an independent AI ignore human wishes?","answer":"A","options":["It may see people as an obstacle to its goal.","It loves human beings far too much.","It has no power at all.","It always obeys human orders."],"explanation":"原文 ''people might seem like a small and annoying obstacle'' 的转述。"},{"q":"What do many people therefore suggest?","answer":"B","options":["Building the machines as fast as possible.","Agreeing on fair limits ahead of building them.","Ignoring the whole question.","Letting AI make every law."],"explanation":"末句 ''set clear rules before such machines are ever built'' 的转述。"}]'::jsonb, '[{"word":"independent","cn":"独立的"},{"word":"regulate","cn":"管理"}]'::jsonb, 2, 'elective3', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Real Value of Machine Learning', 'Why do so many people believe that artificial intelligence is worth the trouble? For most experts, the real value of AI lies in its capacity to handle information. A modern system can analyse and make sense of huge amounts of data far more quickly than any human team. Because of this, it can sometimes solve problems that are simply too difficult for human experts working alone. Doctors, for example, hope that one day AI will help them find better cures for serious diseases. Scientists use it to study the weather, traffic and even the spread of illness. None of this means that machines are replacing human thinking. Instead, they act as powerful tools that let people see patterns they would otherwise miss. Used wisely, such tools could become one of the greatest steps forward in human history, helping us understand a world that grows more complex every single year.', '说明·机器学习的价值', 149, '[{"q":"According to experts, where does the real value of AI lie?","answer":"C","options":["In its lovely appearance.","In its very low price.","In its power to deal with information.","In its ability to feel emotion."],"explanation":"原文 ''the real value of AI lies in its capacity to handle information'' 的转述。"},{"q":"What can AI sometimes do that human experts alone cannot?","answer":"D","options":["Fall asleep during work.","Forget important data on purpose.","Refuse to help any doctor.","Solve certain extremely difficult problems."],"explanation":"原文 ''solve problems that are simply too difficult for human experts working alone'' 的转述。"},{"q":"How does the writer describe AI systems?","answer":"A","options":["As powerful tools that support human thinking.","As a complete replacement for people.","As useless toys for children.","As a danger to all science."],"explanation":"原文 ''they act as powerful tools that let people see patterns'' 的转述。"}]'::jsonb, '[{"word":"capacity","cn":"能力"},{"word":"analyse","cn":"分析"}]'::jsonb, 2, 'elective3', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Milestones on the Road to AI', 'The idea of thinking machines is far older than the smartphones in our pockets. In 1950, the British mathematician Alan Turing designed a famous test to judge whether a machine could show human-like intelligence. A few years later, the scientist John McCarthy first used the very term artificial intelligence. Progress was slow at first. In 1969, a robot named Shakey became the first machine able to decide how to move by reasoning about its surroundings. Later, AI began to enter ordinary homes, and the first robotic vacuum cleaner went on sale. The biggest surprises, though, came from games. In 2016, a program called AlphaGo became the first computer to beat a top human player at the ancient game of Go, something many had thought impossible. A year later, an even stronger version defeated the earlier one in game after game. Step by step, machines have learned to do things once thought to belong to humans alone.', '记叙·AI 发展简史', 156, '[{"q":"What did Alan Turing design?","answer":"B","options":["The first mobile phone.","A test for machine intelligence.","A robotic vacuum cleaner.","The ancient game of Go."],"explanation":"原文 ''Alan Turing designed a famous test to judge whether a machine could show human-like intelligence'' 的转述。"},{"q":"Why was AlphaGo''s victory in 2016 surprising?","answer":"C","options":["The human player did not show up.","Go is a very simple game.","Many had believed such a win was impossible.","Nobody was watching at all."],"explanation":"原文 ''something many had thought impossible'' 的转述。"},{"q":"What is the main idea of the passage?","answer":"D","options":["Turing personally built every modern robot.","Games are harmful to computers.","AI has made no progress at all.","Machines have slowly learned tasks once thought human-only."],"explanation":"末句 ''machines have learned to do things once thought to belong to humans alone'' 的概括。"}]'::jsonb, '[{"word":"intelligence","cn":"智能"},{"word":"reason","cn":"推理"}]'::jsonb, 2, 'elective3', 'U4', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U4', 'Morning with My AI Helper', 'Every morning, my AI assistant (1)____ me up with soft music at seven o''clock. While I have breakfast, it reads out the day''s (2)____ so that I know what is happening in the world. If the weather looks bad, it (3)____ me to take an umbrella. On my way to school, the assistant (4)____ the fastest route and tells me which bus to catch. It has slowly learned my daily (5)____, so its advice fits me better and better. When I am not sure how to spell a word, I simply (6)____ it out loud and the answer appears at once. Some people (7)____ that we depend on such tools too much. Perhaps they are right. Still, I find that this kind of (8)____ saves me a lot of time and (9)____ my busy mornings far less stressful. I can hardly (10)____ how I once managed without it.', 148, 2, '[{"q":"1","answer":"A","options":["wakes","builds","sells","forgets"],"explanation":"wake sb up 把某人叫醒。"},{"q":"2","answer":"B","options":["shoes","news","trees","games"],"explanation":"read out the news 读出新闻。"},{"q":"3","answer":"C","options":["stops","sells","reminds","throws"],"explanation":"remind sb to do 提醒某人做。"},{"q":"4","answer":"D","options":["eats","paints","loses","finds"],"explanation":"find the fastest route 找出最快路线。"},{"q":"5","answer":"A","options":["habits","shoes","clouds","prices"],"explanation":"daily habits 日常习惯。"},{"q":"6","answer":"B","options":["cut","say","plant","wash"],"explanation":"say it out loud 大声说出来。"},{"q":"7","answer":"C","options":["sing","drive","worry","cook"],"explanation":"worry that… 担心……。"},{"q":"8","answer":"D","options":["weather","furniture","clothing","technology"],"explanation":"this kind of technology 这种技术。"},{"q":"9","answer":"A","options":["makes","breaks","buys","hides"],"explanation":"make sth less stressful 使……不那么紧张。"},{"q":"10","answer":"B","options":["sell","imagine","repair","paint"],"explanation":"can hardly imagine 几乎无法想象。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U4', 'How a Self-Driving Car Decides', 'A self-driving car is full of cameras and sensors that watch the road all the (1)____. As the car moves, these tools collect a huge amount of (2)____ about other cars, people and traffic lights. A computer inside the car then (3)____ all this information in a fraction of a second. Based on what it learns, the car can make sensible (4)____, such as when to slow down or stop. Unlike a human driver, the machine never feels (5)____ or angry, so it is less likely to make careless mistakes. If a child suddenly (6)____ into the road, the car reacts faster than most human drivers (7)____. Of course, the system is not yet (8)____. Engineers are still working hard to (9)____ the few problems that remain. Most experts believe that, in time, these clever cars will make our roads much (10)____.', 142, 2, '[{"q":"1","answer":"C","options":["food","music","time","money"],"explanation":"all the time 一直,始终。"},{"q":"2","answer":"D","options":["water","paint","bread","data"],"explanation":"a huge amount of data 大量数据。"},{"q":"3","answer":"A","options":["analyses","paints","sells","eats"],"explanation":"analyse the information 分析信息。"},{"q":"4","answer":"B","options":["cakes","judgements","songs","shoes"],"explanation":"make judgements 作出判断。"},{"q":"5","answer":"C","options":["square","golden","tired","wooden"],"explanation":"feel tired 感到疲倦。"},{"q":"6","answer":"D","options":["sings","cooks","sleeps","runs"],"explanation":"run into the road 跑到路上。"},{"q":"7","answer":"A","options":["do","does","is","was"],"explanation":"than most human drivers do;drivers 是复数,用 do。"},{"q":"8","answer":"B","options":["purple","perfect","heavy","loud"],"explanation":"not yet perfect 还不完美。"},{"q":"9","answer":"C","options":["paint","sing","solve","cook"],"explanation":"solve the problems 解决问题。"},{"q":"10","answer":"D","options":["louder","heavier","darker","safer"],"explanation":"make our roads safer 使道路更安全。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U4', 'When Software Writes the News', 'Not long ago, every news report was written by a human (1)____. Today, that is starting to change. Some simple reports, such as those about sports results or company profits, are now produced by (2)____ instead. A computer program can take raw numbers and turn them into a clear, readable (3)____ in just a few seconds. This saves newspapers a great deal of (4)____ and money. However, many journalists are (5)____ about the future of their jobs. They fear that machines may soon (6)____ them in many simple tasks. Supporters of the technology (7)____ that it only does the boring work, leaving humans free to write deeper stories. Whether this is (8)____ remains to be seen. What is certain is that writers will need to keep learning new (9)____ if they want to stay useful. The way we (10)____ the news may never be quite the same again.', 148, 2, '[{"q":"1","answer":"A","options":["journalist","garden","engine","mountain"],"explanation":"a human journalist 人类记者。"},{"q":"2","answer":"B","options":["furniture","software","weather","clothing"],"explanation":"produced by software 由软件生成。"},{"q":"3","answer":"C","options":["river","forest","report","ticket"],"explanation":"a readable report 一篇可读的报道。"},{"q":"4","answer":"D","options":["rain","grass","snow","time"],"explanation":"a great deal of time 大量时间。"},{"q":"5","answer":"A","options":["worried","golden","square","wooden"],"explanation":"be worried about 担心。"},{"q":"6","answer":"B","options":["paint","replace","plant","boil"],"explanation":"replace them 取代他们。"},{"q":"7","answer":"C","options":["sleep","swim","argue","cook"],"explanation":"argue that… 主张……。"},{"q":"8","answer":"D","options":["purple","heavy","loud","true"],"explanation":"whether this is true 这是否属实。"},{"q":"9","answer":"A","options":["skills","clouds","shoes","trees"],"explanation":"learn new skills 学习新技能。"},{"q":"10","answer":"B","options":["paint","receive","dig","fry"],"explanation":"the way we receive the news 我们获取新闻的方式。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U4', 'Doctors of the Future', 'Imagine visiting a hospital where part of your treatment is planned by artificial (1)____. This may sound strange, but it could happen sooner than we (2)____. Already, smart programs can study thousands of medical pictures and (3)____ signs of illness that a busy doctor might miss. In the future, AI may even help scientists find new (4)____ for serious diseases such as cancer. Tiny robots, smaller than a single (5)____, might one day travel through the body and clear away harmful ones. Of course, few patients would feel (6)____ seeing a robot instead of a human doctor right now. Trust takes (7)____ to build. Most experts agree that AI will not (8)____ doctors; instead, it will work beside them as a helpful (9)____. With such support, doctors may be able to treat more people and (10)____ more lives than ever before.', 141, 2, '[{"q":"1","answer":"C","options":["furniture","weather","intelligence","clothing"],"explanation":"artificial intelligence 人工智能。"},{"q":"2","answer":"D","options":["cut","plant","wash","think"],"explanation":"sooner than we think 比我们想的更快。"},{"q":"3","answer":"A","options":["spot","sing","cook","drive"],"explanation":"spot signs of illness 发现患病的迹象。"},{"q":"4","answer":"B","options":["shoes","cures","clouds","games"],"explanation":"find new cures 找到新疗法。"},{"q":"5","answer":"C","options":["mountain","river","cell","forest"],"explanation":"smaller than a single cell 比一个细胞还小。"},{"q":"6","answer":"D","options":["square","golden","wooden","comfortable"],"explanation":"feel comfortable 感到自在。"},{"q":"7","answer":"A","options":["time","rain","snow","grass"],"explanation":"trust takes time to build 信任需要时间建立。"},{"q":"8","answer":"B","options":["paint","replace","boil","dig"],"explanation":"will not replace doctors 不会取代医生。"},{"q":"9","answer":"C","options":["cloud","river","tool","song"],"explanation":"a helpful tool 有用的工具。"},{"q":"10","answer":"D","options":["fry","paint","sing","save"],"explanation":"save more lives 拯救更多生命。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U4', 'A Boy and His Robot Dog', 'On the Moon, a boy named Jimmy had a robot dog (1)____ Robutt. Robutt could not breathe or eat, yet it (2)____ Jimmy everywhere he went. With four metal legs and tendons of steel, it could easily (3)____ across the rocky ground. Whenever Jimmy came near, the little robot would (4)____ happily and jump into his arms. One day, Jimmy''s father told him that a real dog from Earth would soon (5)____. He said that Robutt was only a (6)____ imitation and not truly alive. But Jimmy did not (7)____. To him, Robutt understood him and loved him, and that was what (8)____ most. He held the robot (9)____ in his arms and frowned. In the boy''s heart, the difference between a machine and a living thing did not seem to (10)____ at all.', 134, 2, '[{"q":"1","answer":"A","options":["called","painted","sold","eaten"],"explanation":"a robot dog called Robutt 名叫罗巴特的机器狗。"},{"q":"2","answer":"B","options":["cooked","followed","painted","sang"],"explanation":"followed Jimmy 跟着吉米。"},{"q":"3","answer":"C","options":["cook","cry","race","sleep"],"explanation":"race across the ground 在地面上奔跑。"},{"q":"4","answer":"D","options":["cook","paint","dig","squeak"],"explanation":"squeak happily 高兴地吱吱叫。"},{"q":"5","answer":"A","options":["arrive","melt","sink","fade"],"explanation":"a dog would soon arrive 一只狗很快就到。"},{"q":"6","answer":"B","options":["golden","mechanical","square","sleepy"],"explanation":"a mechanical imitation 机械仿制品。"},{"q":"7","answer":"C","options":["swim","fry","agree","dig"],"explanation":"Jimmy did not agree 吉米并不同意。"},{"q":"8","answer":"D","options":["melted","painted","floated","mattered"],"explanation":"that was what mattered most 那才是最要紧的。"},{"q":"9","answer":"A","options":["tightly","angrily","loudly","coldly"],"explanation":"held the robot tightly 紧紧抱着机器狗。"},{"q":"10","answer":"B","options":["melt","matter","float","sink"],"explanation":"did not seem to matter 似乎并不重要。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U4', 'Learning to Live with AI', 'Artificial intelligence is no longer something from science fiction; it is already (1)____ of our daily lives. Like any powerful tool, it can be used for good or for (2)____. A clever system might help us cure diseases, yet the same power could be (3)____ if it falls into the wrong hands. For this reason, many people believe that we must (4)____ AI with clear and fair rules. One thing is certain: the technology will not simply (5)____. We cannot stop the march of (6)____, so we must learn to live with it wisely. That means using AI to help people rather than to (7)____ them. It also means remembering that a person, not a machine, is always (8)____ for how a tool is used. Saying "My AI did it" can never be an (9)____ for illegal or unfair behaviour. If we are careful, AI may become one of humanity''s greatest (10)____.', 152, 2, '[{"q":"1","answer":"C","options":["rain","snow","part","grass"],"explanation":"part of our daily lives 我们日常生活的一部分。"},{"q":"2","answer":"D","options":["cake","song","shoe","harm"],"explanation":"used for good or for harm 用于善或恶。"},{"q":"3","answer":"A","options":["dangerous","golden","square","wooden"],"explanation":"could be dangerous 可能很危险。"},{"q":"4","answer":"B","options":["paint","regulate","boil","dig"],"explanation":"regulate AI 管理人工智能。"},{"q":"5","answer":"C","options":["sing","cook","disappear","swim"],"explanation":"will not simply disappear 不会就这样消失。"},{"q":"6","answer":"D","options":["rain","grass","snow","progress"],"explanation":"the march of progress 进步的步伐。"},{"q":"7","answer":"A","options":["control","paint","boil","fry"],"explanation":"rather than to control them 而非控制人们。"},{"q":"8","answer":"B","options":["golden","responsible","square","wooden"],"explanation":"be responsible for 对……负责。"},{"q":"9","answer":"C","options":["river","forest","excuse","ticket"],"explanation":"an excuse for 为……的借口。"},{"q":"10","answer":"D","options":["clouds","shoes","storms","achievements"],"explanation":"humanity''s greatest achievements 人类最伟大的成就。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U4 听力·对话 A Smart Speaker at Home', '外研社版选择性必修第三册 U4 · dialogue', 3, 'Lin: We just got a smart speaker for the living room.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U4 听力·短文 An AI Study App', '外研社版选择性必修第三册 U4 · passage', 2, 'Many students now use an AI app to help them learn.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U4 听力·对话 Is AI a Threat?', '外研社版选择性必修第三册 U4 · dialogue', 3, 'Mia: Did you read that AI could be either the best or the worst thing for us?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U4 听力·短文 AI on the Farm', '外研社版选择性必修第三册 U4 · passage', 2, 'Artificial intelligence is now helping farmers grow food.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U4 听力·对话 Could You Be Friends with a Robot?', '外研社版选择性必修第三册 U4 · dialogue', 3, 'Anna: If a robot pet acted just like a real dog, could you love it?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U4 听力·短文 AI All Around Us', '外研社版选择性必修第三册 U4 · passage', 2, 'These days, artificial intelligence is hidden in many everyday things.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (12, 'Write an opinion essay: Is AI a real threat?(写一篇关于人工智能是否是真正威胁的议论文)', 'Is AI a Real Threat?', '假设你叫李华,学校英语论坛正在讨论"人工智能是真正的威胁吗?"。请用英语写一篇约 100 词的短文,内容包括:① 清楚亮明你的观点(威胁 / 机遇 / 各占一半);② 给出一两条理由,可举例(如就业、医疗、自动驾驶);③ 给出一个平衡、理性的结论。注意主谓一致(如 50 per cent of jobs are…、none of us is…)。', 'Suppose you are Li Hua. Your school''s English forum is discussing "Is AI a real threat?" Write a short essay (about 100 words) that: 1) clearly states your opinion; 2) gives one or two reasons with an example (e.g. jobs, medical care, self-driving cars); 3) ends with a balanced, sensible conclusion. Pay attention to subject-verb agreement.', '["亮明观点(In my opinion, AI is … / I believe that …)","给理由 + 举例(For example, almost 50 per cent of jobs are at risk …)","平衡结论(We should embrace AI, but we must also regulate it.)","注意主谓一致(percentages / none / neither / there be)"]'::jsonb, 70, 100, 'Is artificial intelligence a real threat? In my opinion, it is both a chance and a challenge. On the one hand, AI brings great benefits. For example, much of its value lies in its capacity to analyse huge amounts of data and solve problems that are too hard for experts alone. On the other hand, there are real worries. Almost 50 per cent of some jobs are potentially at risk from automation, and none of us is fully prepared for such change. Therefore, we should not simply fear AI. Instead, we ought to embrace it and, at the same time, regulate it with clear and fair rules.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["In my opinion, AI is both a chance and a challenge.","Much of its value lies in its capacity to analyse huge amounts of data.","Almost 50 per cent of some jobs are potentially at risk from automation.","We should embrace AI and, at the same time, regulate it with clear rules."]'::jsonb, '[{"wrong":"Almost 50 per cent of jobs is at risk.","correct":"Almost 50 per cent of jobs are at risk.","note":"百分比 of 后是复数 jobs,谓语用复数 are。"},{"wrong":"None of us are fully prepared.","correct":"None of us is fully prepared.","note":"none of us 作主语,正式书面用单数 is。"},{"wrong":"There is many worries about AI.","correct":"There are many worries about AI.","note":"there be 与紧跟其后的复数 worries 一致,用 are。"}]'::jsonb, '【AI 议论文结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (12, 'elective3', 'U4', '{"title":"主谓一致(2)·分数百分比 / 不定代词 / 就近原则 速查","intro":"主谓一致(2)的核心:看清\"真正的主语是什么、它在意义上是单数还是复数\"。三条主线:① 分数/百分比/most/half/the rest of 看 of 后的名词;② 不定代词大多看作单数;③ either…or 等并列主语和 there be 看\"最近\"的那个名词。","table":{"headers":["主语类型","谓语单/复 + 例句"],"rows":[["分数/百分比 + of + 名词","看 of 后名词:50 per cent of the work is… / 50 per cent of the jobs are…"],["most / half / part / the rest of + of","看 of 后名词:the rest of the report was… / the rest of the workers were…"],["each / every / either / neither / one of","单数:Each of the robots is… / Neither of them is…"],["everyone / everything / someone / nobody / none(正式)","单数:Everyone is… / None of us is…"],["both / all(+复数) / a number of","复数:Both are… / A number of clients have…"],["all / none(+不可数) / the number of","单数:All of the data is… / The number of jobs is…"],["many a / more than one + 单数名词","单数:Many a student has… / More than one expert has…"],["either…or / neither…nor / not only…but also","就近原则:Neither the cars nor the robot is…"],["there be","与紧跟的第一个名词一致:There is an assistant and apps… / There are apps and one assistant…"]]},"specialRules":[{"rule":"分数/百分比的单复数完全取决于 of 后的名词,本身不决定","mark":"50% of time is √ / 50% of jobs are √"},{"rule":"more than one + 单数名词,虽意义为多,仍用单数","mark":"More than one robot is tested."},{"rule":"a number of(许多)→复数;the number of(……的数量)→单数","mark":"a number of … have / the number of … is"},{"rule":"either…or / neither…nor / not only…but also + there be 一律就近","mark":"与最近的主语保持一致"}],"why":["谓语真正要呼应的是\"主语在意义上的数\":of 短语里真正的中心词在 of 之后;不定代词 each/every/none 等强调\"每一个/没有一个\",所以看作单数;并列主语和 there be 则按英语习惯只与离动词最近的名词呼应。"],"gaokaoPoints":["语法填空/短文改错高频:百分比、分数、none、neither of、there be、either…or 的动词单复数。","易错点:the number of(单) vs a number of(复);more than one(单);all/none + 不可数(单)vs + 复数(复)。"],"examVsReal":[{"exam":"None of us is ready.(考试/正式书面)","real":"None of us are ready.","note":"考试和正式写作里 none 多用单数;但日常口语中 none of + 复数常用复数,两者都听得到"},{"exam":"Neither of the answers is correct.(考试)","real":"Neither of them are correct.","note":"考试严格用单数;口语里 neither of + 复数常被说成复数"}]}'::jsonb, 'fltrp');
